import re, sys, os
root = sys.argv[1]
ev = os.path.join(root, 'docs/evidence')
def read(p):
    try: return open(os.path.join(ev, p)).read()
    except FileNotFoundError: return ''
l2 = read('L2-failover.md')
def rto(mode):
    m = re.search(r'\| \[%s\]\(L2/%s\.md\) \| ([^|]+) \| ([^|]*) \|' % (mode, mode), l2)
    return (m.group(1).strip(), m.group(2).strip()) if m else ('?', '?')
def parts(f):
    rows = re.findall(r'^\| [^|]+ \| (PASS|FAIL|OVER TARGET)[^|]* \| (\d+) of (\d+) \|', read(f), re.M)
    p = sum(1 for r in rows if r[0] == 'PASS')
    return '%d of %d parts PASS' % (p, len(rows))
def res(f):
    m = re.search(r'\*\*Result: ([A-Z ]+)\*\*', read(f)); return m.group(1) if m else '?'
rpo_vals = re.findall(r'\| (\d+) \| \d+ \| (?:restart only|re-?clone[^|]*|[^|]*) \|', '')
sec = read('L6-security.md'); sp = sec.count('| PASS'); sf = sec.count('| FAIL')
rpo_rows = []
for f in sorted(os.listdir(os.path.join(ev, 'L2'))):
    for line in open(os.path.join(ev, 'L2', f)):
        c = [x.strip() for x in line.split('|')]
        if len(c) > 9 and re.fullmatch(r'\d+', c[1] or '') and re.fullmatch(r'\d+', c[7] or ''):
            rpo_rows.append(int(c[7]))
rpo = 'max %d acknowledged rows lost over %d runs' % (max(rpo_rows), len(rpo_rows)) if rpo_rows else '?'
for k in ['pod', 'node', 'storage', 'split-brain', 'switchover', 'chain', 'diverge']:
    print(k, rto(k))
print('rpo', rpo)
print('L1', res('L1-replication.md'))
print('L3', parts('L3-backup.md'))
print('L4', parts('L4-restore.md'))
print('L5', parts('L5-monitoring.md'))
print('L6', res('L6-security.md'), sp, sf)

